style.css:
@-moz-document domain("roblox.com") {
html, body {
    height: 100%;
    margin: 0;
    padding: 0;
  }

  body {
    background: url("https://imgur.com/gallery/sukuna-WBnP5fD") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Also target main Roblox container */
  #container, #container-viewport {
    background: transparent !important;
  }
}
